/* Local in-app due-date planner. No push delivery or network traffic. */
(function(){'use strict';
const STORE='nando-recordatorios-v1';let preferences={},readOnly=false,agendaOpen=false,agendaDirty=false;
try{const raw=localStorage.getItem(STORE);if(raw!==null){const parsed=JSON.parse(raw);if(!parsed||typeof parsed!=='object'||Array.isArray(parsed))throw Error('invalid');preferences=Object.assign(Object.create(null),parsed)}}catch(_){readOnly=true}
const root=document.createElement('section');root.className='overview';root.style.marginTop='20px';root.setAttribute('aria-label','Recordatorios de obligaciones');
root.innerHTML='<h2>Recordatorios de corte y pago</h2><p class="label">Consulta próximos avisos cuando abras esta pantalla. Esta versión no envía notificaciones en segundo plano.</p><p class="label">La fecha de corte cierra el período; la fecha límite de pago es el último día indicado por la entidad. Pagar el mínimo no garantiza evitar intereses; el período de gracia depende de la entidad y de tu saldo.</p><div class="actions"><button type="button" id="rem-open">Configurar y consultar</button></div><div id="rem-content"></div>';
const layout=document.querySelector('.layout');if(!layout||!layout.parentNode)return;layout.parentNode.insertBefore(root,layout);
const $=id=>document.getElementById(id);const dayValue=x=>x===''?null:Number(x);
function elem(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n}
function safePrefs(){try{const raw=localStorage.getItem(STORE);if(raw===null)return Object.create(null);const d=JSON.parse(raw);if(!d||typeof d!=='object'||Array.isArray(d))throw Error();return Object.assign(Object.create(null),d)}catch(_){readOnly=true;throw Error('No se pudieron leer las preferencias anteriores. No se modificó ninguna información.') }}
function field(parent,title,type,value,attrs={}){const wrap=elem('label',undefined,'field');wrap.append(elem('span',title));const input=document.createElement('input');input.type=type;input.value=value==null?'':String(value);for(const [key,val] of Object.entries(attrs))input.setAttribute(key,String(val));wrap.append(input);parent.append(wrap);return input}
function checkbox(parent,text,checked){const label=elem('label');const input=document.createElement('input');input.type='checkbox';input.checked=checked;label.append(input,document.createTextNode(' '+text));parent.append(label,document.createElement('br'));return input}
function show(){agendaOpen=true;agendaDirty=false;const content=$('rem-content');content.replaceChildren();let readVersion;try{preferences=safePrefs();readVersion=localStorage.getItem(STORE)}catch(_){readOnly=true}if(readOnly){content.append(elem('p','No se pudieron leer las preferencias de recordatorios. No se ha modificado la información. Conserva una copia antes de intentar recuperarla.','error'));return}let all;try{all=Array.isArray(debts)?debts:[]}catch(_){content.append(elem('p','No fue posible leer las obligaciones.','error'));return}if(!all.length){content.append(elem('p','Agrega una deuda para configurar sus fechas.','label'));return}
for(const debt of all){const id=String(debt.id),old=preferences[id]||{},card=elem('div',undefined,'card');card.append(elem('h3',String(debt.name)));const form=document.createElement('form');const cutoff=field(form,'Día de corte (1 a 31, opcional)','number',old.cutoffDay,{min:1,max:31,step:1});const due=field(form,'Día de pago (1 a 31, opcional)','number',old.paymentDay??debt.due??'',{min:1,max:31,step:1});const paid=field(form,'Marcar pagos cumplidos hasta esta fecha (opcional)','date',old.paidThrough);const before=field(form,'Avisar cuántos días antes','number',old.beforeDays??3,{min:0,max:90,step:1});const cutoffOn=checkbox(form,'Mostrar avisos de corte',old.cutoffEnabled!==false);const paymentOn=checkbox(form,'Mostrar avisos de pago',old.paymentEnabled!==false);const sameDay=checkbox(form,'Incluir aviso el día del evento',old.sameDay!==false);const error=elem('p','','error');error.setAttribute('role','status');let save=elem('button','Guardar recordatorios','ghost');save.type='submit';form.append(error,save);form.onsubmit=e=>{e.preventDefault();try{if(typeof storageLocked!=='undefined'&&storageLocked)throw Error('Hay datos pendientes de revisión. No se guardarán recordatorios.');if(!form.reportValidity())return;const cutoffDay=dayValue(cutoff.value),paymentDay=dayValue(due.value),beforeDays=Number(before.value);if(before.value===''||!Number.isInteger(beforeDays)||beforeDays<0||beforeDays>90)throw Error('Indica los días de anticipación entre 0 y 90.');for(const n of [cutoffDay,paymentDay])if(n!==null&&(!Number.isInteger(n)||n<1||n>31))throw Error('Las fechas deben ser días del 1 al 31.');if(paid.value)DebtReminders.parseDate(paid.value);if(localStorage.getItem(STORE)!==readVersion)throw Error('Las preferencias cambiaron en otra pestaña. Copia tus cambios y vuelve a abrir la agenda para revisarlos; no se sobrescribió información.');const current=safePrefs();current[id]={cutoffDay,paymentDay,paidThrough:paid.value||null,beforeDays,cutoffEnabled:cutoffOn.checked,paymentEnabled:paymentOn.checked,sameDay:sameDay.checked};const encoded=JSON.stringify(current);(localStorage.getItem('nando-restore-journal-v1')!==null?(()=>{throw Error('Hay una recuperación pendiente; no se guardó ningún cambio.')})():localStorage.setItem(STORE,encoded));if(localStorage.getItem(STORE)!==encoded)throw Error('No se pudo confirmar el guardado.');preferences=current;show()}catch(err){error.textContent=err.message||'No fue posible guardar. Tus datos anteriores se mantienen.'}};card.append(form);content.append(card)}
const today=DebtReminders.dateInZone(new Date(),Intl.DateTimeFormat().resolvedOptions().timeZone);const upcoming=elem('div');upcoming.append(elem('h3','Próximos avisos (30 días)'));let events=[];for(const debt of all){let p=preferences[String(debt.id)]||{};try{const before=Number.isInteger(p.beforeDays)?p.beforeDays:3, offsets=p.sameDay===false?[before]:[before,0];events.push(...DebtReminders.schedule([{id:String(debt.id),name:String(debt.name),cutoffDay:p.cutoffDay,paymentDay:p.paymentDay??debt.due??null,cutoffEnabled:p.cutoffEnabled,paymentEnabled:p.paymentEnabled,paidThrough:p.paidThrough}],{today,offsets,daysAhead:30,locale:document.documentElement.lang}))}catch(_){upcoming.append(elem('p','Revisa la configuración de '+String(debt.name)+'.','error'))}}events.sort((a,b)=>a.notifyDate.localeCompare(b.notifyDate));if(!events.length)upcoming.append(elem('p','No hay avisos programados para los próximos 30 días.','label'));else{const ul=elem('ul');for(const event of events){const li=elem('li',`${event.notifyDate}: ${DebtReminders.message(event,document.documentElement.lang)} (${event.formattedDate}).`);ul.append(li)}upcoming.append(ul)}upcoming.append(elem('p','Si un día no existe en un mes, se muestra el último día de ese mes como referencia; confirma la fecha con tu entidad. Estas fechas no confirman ni realizan pagos.','label'));content.append(upcoming)
}
$('rem-open').addEventListener('click',show);
$('rem-content').addEventListener('input',()=>{agendaDirty=true});
$('rem-content').addEventListener('change',()=>{agendaDirty=true});
document.addEventListener('deudas:languagechange',()=>{if(agendaOpen&&!agendaDirty)show()});
})();
